    const found = rulesAtParent(harness, repoPath, session.commit_sha);
    if (found) ({ rulesHash, rulesPath } = found);
  }
  return {
    setupId: setupIdOf(harness, model, rulesHash),
    harness,
    model,
    rulesHash,
    rulesPath,
    tag: parseTag(session.first_prompt),
  };
}

/**
